-- The exercise library, imported from free-exercise-db (public domain). Clients only read it;
-- it changes through migrations generated by scripts/import-exercises.ts.

-- The fixed sets of values free-exercise-db uses. Enums rather than check constraints, so
-- that the generated TypeScript types list the values. A new upstream value is added with
-- `alter type ... add value`.
create type public.exercise_level as enum ('beginner', 'intermediate', 'expert');

create type public.exercise_category as enum (
  'strength',
  'stretching',
  'plyometrics',
  'powerlifting',
  'olympic weightlifting',
  'strongman',
  'cardio'
);

create type public.equipment as enum (
  'barbell',
  'dumbbell',
  'body only',
  'cable',
  'machine',
  'kettlebells',
  'bands',
  'medicine ball',
  'exercise ball',
  'foam roll',
  'e-z curl bar',
  'other'
);

create type public.exercise_force as enum ('push', 'pull', 'static');

create type public.exercise_mechanic as enum ('compound', 'isolation');

create type public.muscle as enum (
  'abdominals',
  'abductors',
  'adductors',
  'biceps',
  'calves',
  'chest',
  'forearms',
  'glutes',
  'hamstrings',
  'lats',
  'lower back',
  'middle back',
  'neck',
  'quadriceps',
  'shoulders',
  'traps',
  'triceps'
);

create table public.exercises (
  -- The upstream id, such as 'Barbell_Squat', so that later imports can update rows in place.
  id text primary key check (id ~ '^[A-Za-z0-9_-]+$'),
  -- In English. Names in other languages are in exercise_translations.
  name text not null,
  level public.exercise_level not null,
  category public.exercise_category not null,
  equipment public.equipment,
  force public.exercise_force,
  mechanic public.exercise_mechanic,
  primary_muscles public.muscle[] not null,
  secondary_muscles public.muscle[] not null,
  -- Steps in English only for now.
  instructions text[] not null,
  -- Paths in the exercise-images Storage bucket, usually the start and end position.
  image_paths text[] not null
);

create table public.exercise_translations (
  exercise_id text not null references public.exercises (id) on delete cascade,
  -- English is the source in exercises and is not repeated here.
  language text not null check (language in ('de', 'tr')),
  name text not null,
  primary key (exercise_id, language)
);

-- Everyone using the app, including anonymous users, can read the library. There are no
-- insert, update or delete policies, so clients cannot change it, and the privileges are
-- revoked as well so that a policy added by mistake would not be enough.
alter table public.exercises enable row level security;
alter table public.exercise_translations enable row level security;

create policy "Exercises are readable by everyone"
  on public.exercises for select
  to anon, authenticated
  using (true);

create policy "Exercise translations are readable by everyone"
  on public.exercise_translations for select
  to anon, authenticated
  using (true);

revoke insert, update, delete, truncate on public.exercises from anon, authenticated;
revoke insert, update, delete, truncate on public.exercise_translations from anon, authenticated;
